def run(name,G,full,si,n):
    sets,hi,comps=M[name]; S=len(sets); his=np.array([s>=hi for s in sets])
    use=[c for c in comps if c[4] or full]
    ok=0
    for _ in range(n):
        cnt={}; ll=np.zeros(S)
        for nm,kind,arr,den,req in use:
            if kind=='g':
                k=rng.binomial(G,1/arr[si]); cnt[nm]=k; ll+=k*np.log(1/arr)+(G-k)*np.log(1-1/arr)
        for nm,kind,arr,den,req in use:
            if kind=='pct':
                t=sum(cnt.get(d,0) for d in den)
                if t>0:
                    k=rng.binomial(t,arr[si]/100); ll+=k*np.log(arr/100)+(t-k)*np.log(1-arr/100)
            if kind=='bt':
                t=int(round(cnt.get(den[0],0)*den[1]))
                if t>0:
                    k=rng.binomial(t,1/arr[si]); ll+=k*np.log(1/arr)+(t-k)*np.log(1-1/arr)
        w=np.exp(ll-ll.max()); p=w/w.sum(); ok+= p[his].sum()>=0.8
    return ok/n

