def lv(p): return 'easy' if p>=0.6 else ('normal' if p>=0.3 else 'hard')
if __name__=='__main__':
    n=int(sys.argv[1]) if len(sys.argv)>1 else 2000
    out={}
    print('機種 | 3000G必須のみ | 3000G全部 | 5000G全部 | 設定1誤判定(3000G全部) | 区分')
    for name in M:
        top=len(M[name][0])-1
        r=[run(name,3000,0,top,n),run(name,3000,1,top,n),run(name,5000,1,top,n),run(name,3000,1,0,n)]
        out[PATH[name]]={'name':name,'req3000':round(r[0]*100),'all3000':round(r[1]*100),'all5000':round(r[2]*100),'false1':round(r[3]*100,1),'lv':lv(r[1])}
        print(f'{name} | {r[0]*100:.0f}% | {r[1]*100:.0f}% | {r[2]*100:.0f}% | {r[3]*100:.1f}% | {lv(r[1])}')
    json.dump(out,open('tools/ease.json','w'),ensure_ascii=False,indent=1)
